function replaceLabel(oldLabel, value, position, color, fontSize) {
  if (oldLabel) scene.remove(oldLabel);
  const fresh = new Text({ text: value, color, fontSize });
  fresh.moveTo(position);
  scene.add(fresh);
  return fresh;
}

function updateNumbers(prevalence) {
  const sick = 1000 * prevalence / 100;
  const healthy = 1000 - sick;
  const truePos = 0.9 * sick;
  const falsePos = 0.1 * healthy;
  const posterior = 100 * truePos / (truePos + falsePos);

  sickLabel = replaceLabel(sickLabel, `SICK\n${sick.toFixed(1)} people`, [-2.25, 1.25, 0], WHITE, 20);
  healthyLabel = replaceLabel(healthyLabel, `HEALTHY\n${healthy.toFixed(1)} people`, [-2.25, -1.25, 0], WHITE, 19);
  truePosLabel = replaceLabel(truePosLabel, `TEST +\n${truePos.toFixed(1)} true +`, [0.8, 1.25, 0], BLACK, 19);
  falsePosLabel = replaceLabel(falsePosLabel, `TEST +\n${falsePos.toFixed(1)} false +`, [0.8, -1.25, 0], BLACK, 18);
  resultLabel = replaceLabel(resultLabel, `Chance sick\nafter + test\n${posterior.toFixed(1)}%`, [4.25, 0, 0], YELLOW, 24);
}

