await scene.play(new AnimationGroup([
  new DrawBorderThenFill(sourceBox),
  new DrawBorderThenFill(sickBox),
  new DrawBorderThenFill(healthyBox),
  new DrawBorderThenFill(truePosBox),
  new DrawBorderThenFill(falsePosBox),
  new DrawBorderThenFill(resultBox)
]));
scene.add(sourceLabel);
await scene.play(new AnimationGroup([
  new Create(branch1), new Create(branch2), new Create(test1),
  new Create(test2), new Create(combine1), new Create(combine2)
]));
updateNumbers(1);

